[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot)
$ErrorActionPreference="Stop";$r=(Resolve-Path -LiteralPath $ProjectRoot).Path;$static=Join-Path $r "backend\src\palwakf_local_agents\command_center\static";$router=Join-Path $r "backend\src\palwakf_local_agents\command_center\router.py";$app=Join-Path $r "backend\src\palwakf_local_agents\app.py";$store=Join-Path $r "backend\src\palwakf_local_agents\command_center\read_only_store.py";$gate=Join-Path $r "scripts\Test-CommandCenterV1RevBStatic.ps1";$f=@();foreach($x in @((Join-Path $static "index.html"),(Join-Path $static "styles.css"),(Join-Path $static "app.js"),$router,$app,$store,$gate)){if(-not(Test-Path -LiteralPath $x -PathType Leaf)){$f+="TARGET_FILE_NOT_FOUND=$x"}};$rt=if(Test-Path $router){Get-Content $router -Raw -Encoding UTF8}else{""};foreach($t in @('StaticFiles(directory=STATIC_ROOT)','@api.get("/dashboard")','@api.get("/system-health")','@app.get(ui_prefix')){if($rt -notmatch [regex]::Escape($t)){$f+="ROUTER_CONTRACT_TOKEN_MISSING=$t"}};$at=if(Test-Path $app){Get-Content $app -Raw -Encoding UTF8}else{""};if($at -notmatch [regex]::Escape('mount_command_center(app, project_root=PROJECT_ROOT)')){$f+='APP_MOUNT_TOKEN_MISSING'}
"PREFLIGHT_FAILURE_COUNT=$($f.Count)";"PREFLIGHT_FAILURES=$($f -join ';')";"UI_TARGET_ROOT=backend/src/palwakf_local_agents/command_center/static";"PATCH_SCOPE=STATIC_ASSETS_ONLY";"APP_ENTRYPOINT_MUTATION=NONE";"ROUTER_MUTATION=NONE";"STORE_MUTATION=NONE";"API_MUTATION=NONE";"TASK_STATE_MUTATION=NONE";"MODEL_EXECUTION=NONE";"PILOT_EXECUTION=NOT_EXECUTED";"PLATFORM_MUTATION=NONE";"DATABASE_ACCESS=NONE";"GIT_WRITE=NONE";"DEPLOYMENT=NONE";"SECRETS_ACCESS=NONE";"MEMORY_WRITE=NONE";if($f.Count){"PREFLIGHT_RESULT=FAIL";exit 1};"PREFLIGHT_RESULT=PASS"